/**
 * Pre-build script: bundles exercises/*.sol and solutions/*.sol
 * into src/exerciseData.ts for the Monaco Editor playground.
 */
import { readFileSync, writeFileSync, readdirSync, existsSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const exercisesDir = join(__dirname, "..", "..", "exercises");
const solutionsDir = join(__dirname, "..", "..", "solutions");
const outFile = join(__dirname, "..", "src", "exerciseData.ts");

if (!existsSync(exercisesDir)) {
  console.log(
    "exercises/ directory not found — skipping exercise bundling (using existing exerciseData.ts)",
  );
  process.exit(0);
}

const exerciseFiles = readdirSync(exercisesDir)
  .filter((f) => f.endsWith(".sol") || f.endsWith(".ts"))
  .sort();
const solutionFiles = existsSync(solutionsDir)
  ? readdirSync(solutionsDir)
      .filter((f) => f.endsWith(".sol") || f.endsWith(".ts"))
      .sort()
  : [];

const escapeTemplate = (s) => s.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$/g, "\\$");

// Build exercise entries: { id, title, description, hints, exercise, solution, language, difficulty }
const entries = [];

for (const exFile of exerciseFiles) {
  const id = exFile.replace(/-exercise\.(sol|ts)$/, "");
  const solFile = exFile.replace("-exercise", "-solution");
  const lang = exFile.endsWith(".ts") ? "typescript" : "sol";

  const exerciseContent = readFileSync(join(exercisesDir, exFile), "utf-8");
  const solutionContent = existsSync(join(solutionsDir, solFile))
    ? readFileSync(join(solutionsDir, solFile), "utf-8")
    : "";

  // Extract title from @title NatSpec or first comment
  const titleMatch = exerciseContent.match(/@title\s+(.+)/);
  const title = titleMatch
    ? titleMatch[1].trim()
    : exFile.replace(/-exercise\.(sol|ts)$/, "").replace(/^\d+-/, "");

  // Extract description from @notice NatSpec
  const noticeMatch = exerciseContent.match(/@notice\s+(.+)/);
  const description = noticeMatch ? noticeMatch[1].trim() : "";

  // Extract hints from "/// Hint:" comments
  const hints = [];
  const hintMatches = exerciseContent.matchAll(/\/\/\/?\s*Hint:\s*(.+)/g);
  for (const m of hintMatches) {
    hints.push(m[1].trim());
  }

  // Estimate difficulty based on TODO count
  const todoCount = (exerciseContent.match(/TODO/g) || []).length;
  const difficulty = todoCount <= 2 ? "beginner" : todoCount <= 4 ? "intermediate" : "advanced";

  entries.push({
    id,
    title,
    description,
    hints,
    exercise: exerciseContent,
    solution: solutionContent,
    language: lang,
    difficulty,
  });
}

let output = "// AUTO-GENERATED by scripts/bundle-exercises.js — do not edit manually\n\n";
output += "export interface ExerciseEntry {\n";
output += "  id: string;\n";
output += "  title: string;\n";
output += "  description: string;\n";
output += "  hints: string[];\n";
output += "  exercise: string;\n";
output += "  solution: string;\n";
output += "  language: string;\n";
output += '  difficulty: "beginner" | "intermediate" | "advanced";\n';
output += "}\n\n";
output += "export const exerciseEntries: ExerciseEntry[] = [\n";

for (const entry of entries) {
  output += `  {\n`;
  output += `    id: "${entry.id}",\n`;
  output += `    title: "${escapeTemplate(entry.title)}",\n`;
  output += `    description: "${escapeTemplate(entry.description)}",\n`;
  output += `    hints: [${entry.hints.map((h) => `"${escapeTemplate(h)}"`).join(", ")}],\n`;
  output += `    exercise: \`${escapeTemplate(entry.exercise)}\`,\n`;
  output += `    solution: \`${escapeTemplate(entry.solution)}\`,\n`;
  output += `    language: "${entry.language}",\n`;
  output += `    difficulty: "${entry.difficulty}",\n`;
  output += `  },\n`;
}

output += "];\n";

writeFileSync(outFile, output, "utf-8");
console.log(`Bundled ${entries.length} exercises with solutions into src/exerciseData.ts`);
